 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    # The most frequent color is the background; non-background objects are
    # solid rectangles contaminated by isolated pixels of other colors.
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)
    seen = set()
    boxes = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                        (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            if len(cells) >= 5:
                rs = [p[0] for p in cells]
                cs = [p[1] for p in cells]
                r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
                area = (r1-r0+1)*(c1-c0+1)
                if area >= 9 and len(cells) / area >= 0.4:
                    boxes.append((r0, r1, c0, c1, color))
    out = [[bg for _ in range(w)] for _ in range(h)]
    for r0, r1, c0, c1, color in boxes:
        for r in range(r0, r1+1):
            for c in range(c0, c1+1):
                out[r][c] = color
    return out
"
